local NewViewBaseLayer = require("hall.NewViewBaseLayer")
local UserClashView = class("UserClashView", NewViewBaseLayer)
local CocosUtil = require("hall.util.CocosUtil")

local EVENTNAME = {
	QUERY_JOIN_GAME_LIMIT = "/queryJoinGameLimit",
	DEL_JOIN_GAME_LIMIT = "/delJoinGameLimit",
}

function UserClashView:ctor(family_id)
    self.family_id = family_id
    local csbPath = "hall/res/FriendScircle/UserClashView.csb"
    UserClashView.super.ctor(self, csbPath)

    self:enableMask(true)
    self:initEvent()
    self.dataList = {}
    --self:createTableView()
    self:InitGame()
end

function UserClashView:initEvent()
    self.item:hide()
    ReqMgr:addHandle("UserClashView", EVENTNAME)

    self._btAddNewClash:onClick(handler(self, self.onUpdate))
end

function UserClashView:onExit()
    ReqMgr:delHandle("UserClashView", EVENTNAME)
end

function UserClashView:Sure2Del(event)

    local data = {}
    local target = event.target
    local key = target.key

    local commtip_data =  {}
    commtip_data.type = 2
    commtip_data.title = "删除"
    commtip_data.content = "你确定要删除这一组同桌限制"

    local function Cancel()

    end

    local function onClickBtnDel()

        local family_id = self.family_id
        local data = {
            groupId = family_id,
            key = key
        }

        ReqMgr:request(EVENTNAME.DEL_JOIN_GAME_LIMIT, data, handler(self , self.onClickBtnDelSuccess))

    end

    commtip_data.callBackSure = CocosUtil:Bind(onClickBtnDel)
    commtip_data.callBackCancel = CocosUtil:Bind(Cancel)
    require("hall.tips.CommonTips"):showTips(commtip_data)
end



function UserClashView:onClickBtnDelSuccess(event)

    local netData = event.netData
    local param = event.param
    local returnCode = netData.returnCode
    local data = netData.data
    local error = netData.error
    if not (returnCode == 0) then
        viewMgr:showTip({text = error})
        return
    end

    self:InitGame()

end

function UserClashView:createClash(userItem, index)
    local ly = ccui.Layout:create()
    local item = self.item:clone()
    item:setPosition(0, 0)
    item:setName("item")
    GameUtils.setNodeNameBindObj(item)
    self:initCellInfo(item,userItem, index)
    ly:addChild(item)
    ly:setName("ly")
    item:show()
    return ly
end

function UserClashView:cellSizeForTable()
    local size = self.item:getSize()
    return size.width, size.height
end

function UserClashView:InitGame()
    local data = {
        groupId = self.family_id
    }
    ReqMgr:request(EVENTNAME.QUERY_JOIN_GAME_LIMIT, data, handler(self , self.QUERY_JOIN_GAME_LIMIT))
end

function UserClashView:QUERY_JOIN_GAME_LIMIT(event)

    local netData = event.netData
    local param = event.param
    local returnCode = netData.returnCode
    local data = netData.data
    local error = netData.error
    dump(netData,'xxxxxxxjklfdafdfd')
    if not (returnCode == 0) then
        viewMgr:showTip({text = error})
        return
    end

    self:initClashData(data or {})
end

function UserClashView:initClashData(allData)
    self._listUserClashs:removeAllChildren()
    self.item:hide()
    local index = 1
    for k,data in pairs(allData or {}) do
        local item = self.item:clone()
        item:show()
        GameUtils.setNodeNameBindObj(item)
        self._listUserClashs:pushBackCustomItem(item)
        item._txtClashName:setString('限制组 ' .. index)
        index = index + 1

        for i = 0, 10 do
            local itemUser = self.item:getChildByName("itemUsers_" .. i)
            itemUser:getChildByName('_imgSmallIcon'):loadTexture("")
            itemUser:getChildByName('_txtNickName'):setString("")
            itemUser:getChildByName('_txtUid'):setString("")
            itemUser:show()
        end

        for index,value in ipairs(data or {}) do
            --最多显示11个,从开始
            if index >= 12 then
                break
            end
            local itemUser = item:getChildByName("itemUsers_" .. (index-1))
            require("hall.GameCommon"):getUserHead(value.smallIcon, nil, nil, itemUser:getChildByName('_imgSmallIcon'), 65)
            itemUser:getChildByName('_txtNickName'):setString(value.nickName)
            itemUser:getChildByName('_txtUid'):setString(value.uid)
            itemUser:show()
        end
        item.btnDel.key = k
        item.btnDel:onClick(handler(self, self.Sure2Del))
        item.btnUpdate.key = k
        item.btnUpdate.data = data
        item.btnUpdate:onClick(handler(self, self.onUpdate))
    end
end

function UserClashView:onUpdate(event)
    local target = event.target
    local data = target.data or nil
    local key = target.key or nil
    local UserClashUpdateView = require("hall.familyCircle.UserClashUpdateView").new(data, self.family_id, key)
    if UserClashUpdateView then
        UserClashUpdateView:addTo(self)
    end

end

function UserClashView:reloadData(data)
    if not data then return end
    self.dataList = data
    dump("yyyyyyyyyyyyyyy")
    self.clashList:reloadData()
end

function UserClashView:onClickBtnReturn(...)
    self:removeSelf()
end

return UserClashView